private Element element;
private Element clonedElement;
private Element childElement;
private Element parentElement;
private String baseUri;
private Attributes attributes;
private Tag tag;
private Set<String> classNames;

@Before
public void setUp() throws Exception {
    baseUri = "http://example.com";
    tag = Tag.html;
    attributes = new Attributes();
    attributes.attr("id", "test");
    attributes.attr("class", "container");
    classNames = new HashSet<>();
    classNames.add("container");
    element = new Element(tag, baseUri, attributes);
    element classNames(classNames);
}

@Test
public void testCloneMethod() {
    clonedElement = element.clone();
    // Check if the clone is not the same object
    Assert.assertNotSame(element, clonedElement);
    // Check if the tag is cloned properly
    Assert.assertEquals(element.tag(), clonedElement.tag());
    // Check if the baseUri is cloned properly
    Assert.assertEquals(element.baseUri(), clonedElement.baseUri());
    // Check if the attributes are cloned properly
    Assert.assertEquals(element.attributes(), clonedElement.attributes());
    // Check if the classNames are null in the clone
    Assert.assertNull(clonedElement.classNames());
}

@Test

public void testCloneWithChildNodes() {
    // Create a child element
    childElement = new Element(Tag.body, baseUri, new Attributes());
    // Add the child to the original element
    element.appendChild(childElement);
    // Clone the element
    clonedElement = element.clone();
    // Check if the child is not cloned in the clone
    Assert.assertEquals(0, clonedElement.children().size());
}

@Test
public void testCloneWithoutChildNodes() {
    // Clone the element without child nodes
    clonedElement = element.clone();
    // Check if the clone has no child nodes
    Assert.assertEquals(0, clonedElement.children().size());
}

@Test
public void testCloneWithAttributes() {
    // Add an attribute to the original element
    element.attr("data-test", "testValue");
    // Clone the element
    clonedElement = element.clone();
    // Check if the attribute is present in the clone
    Assert.assertEquals("testValue", clonedElement.attr("data-test"));
}

@Test
public void testCloneWithoutAttributes() {
    // Remove an attribute from the original element
    element.removeAttr("id");
    // Clone the element
    clonedElement = element.clone();
    // Check if the attribute is not present in the clone
    Assert.assertFalse(clonedElement.hasAttr("id"));
}

@Test
public void testCloneWithClassNames() {
    // Add a class to the original element
    element.addClass("testClass");
    // Clone the element
    clonedElement = element.clone();
    // Check if the class is present in the clone
    Assert.assertTrue(clonedElement.hasClass("testClass"));
}

@Test
public void testCloneWithoutClassNames() {
    // Remove a class from the original element
    element.removeClass("container");
    // Clone the element
    clonedElement = element.clone();
    // Check if the class is not present in the clone
    Assert.assertFalse(clonedElement.hasClass("container"));
}

@Test
public void testCloneWithTextNodes() {
    // Add text to the original element
    element.text("Test text");
    // Clone the element
    clonedElement = element.clone();
    // Check if the text is present in the clone
    Assert.assertEquals("Test text", clonedElement.text());
}

@Test
public void testCloneWithoutTextNodes() {
    // Remove text from the original element
    element.empty();
    // Clone the element
    clonedElement = element.clone();
    // Check if the text is not present in the clone
